(()=>{
  'use strict';
  const C=PianoCore,N=PianoNotation,D=PianoContent,A=PianoAudio,L=PianoLibrary,$=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const defaultState={version:1,minutes:20,goal:'完整弹奏一首简单旋律',bpm:60,hints:true,completed:[],history:[],quiz:[]};
  let state,storageOK=true;
  try{state=C.safeState(JSON.parse(localStorage.getItem('qinjie-state')||JSON.stringify(defaultState)))}catch(e){state=C.safeState(defaultState)}
  let route='home',lesson=0,selected=0,filter=-1,songKind='all',songQuery='',mode='wait',range='all',octave=0,barFirst=1,barLast=1,guide=null,replay=null,session=null,animation=null,result=null,demo=null;
  const builtins=D.exercises.map((e,i)=>({...e,id:'builtin:'+i}));let library=L.empty(),libraryNotice='',pendingSongs=null;
  try{const raw=localStorage.getItem('qinjie-song-library');if(raw)library=L.parse(raw,{allowEmpty:true})}catch(e){libraryNotice='自定义曲库暂时无法读取，请重新导入备份。'+e.message}
  function mountLibrary(){D.exercises=[...builtins,...library.songs.map(L.exercise)]}
  mountLibrary();
  function storeLibrary(pack){try{localStorage.setItem('qinjie-song-library',JSON.stringify(pack));library=pack;mountLibrary();return true}catch(e){toast('曲库未保存：空间不足或存储不可用。请先导出备份。');return false}}
  const held=new Map(),pointers=new Map(),tones=new Map();let audio=null,master=null,toastTimer,tailCapture=null;
  function day(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
  function save(){try{localStorage.setItem('qinjie-state',JSON.stringify({...state,hints:guide?guide.old.hints:state.hints}))}catch(e){storageOK=false;toast('存储空间不可用，请导出记录备份')}}
  function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
  async function ensureAudio(){
    if(!audio){const Constructor=window.AudioContext||window.webkitAudioContext;if(!Constructor){toast('当前系统不支持音频，请更新iPadOS并重启应用');throw Error('No AudioContext')};audio=new Constructor({latencyHint:'interactive'});master=A.createOutput(audio)}
    if(audio.state==='suspended')await audio.resume();
    return audio;
  }
  function sound(note,time,duration,id){
    if(!audio)return;if(tones.has(id))releaseSound(id);
    const v=A.voice(audio,master,note,time??audio.currentTime,duration??8);tones.set(id,v);v.onended=()=>{if(tones.get(id)===v)tones.delete(id)};
  }
  function releaseSound(id){const v=tones.get(id);if(!v||!audio)return;const now=audio.currentTime;if(v.release)v.release(now);else{const param=v.gain.gain;if(typeof param.cancelAndHoldAtTime==='function')param.cancelAndHoldAtTime(now);else{const value=param.value;param.cancelScheduledValues(now);param.setValueAtTime(value,now)}param.linearRampToValueAtTime(0,now+.08);v.nodes.forEach(o=>{try{o.stop(now+.1)}catch(e){}})}tones.delete(id)}

  function closeTail(source){if(!tailCapture||!audio)return;const t=tailCapture;let changed=false;t.capture.forEach((n,i)=>{if(!n.closed&&(source===undefined||n.source===source)){n.closed=true;if(t.recording.notes[i])t.recording.notes[i].duration=Math.min(8,300-n.at,Math.max(.04,audio.currentTime-t.start-n.at));changed=true}});if(changed)save();if(source===undefined||t.capture.every(n=>n.closed))tailCapture=null}
  function silence(){closeTail();for(const id of [...tones.keys()])releaseSound(id);held.clear();pointers.clear();document.querySelectorAll('.key.pressed').forEach(k=>k.classList.remove('pressed'))}
  function tick(time,strong){if(!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=strong?1100:800;g.gain.setValueAtTime(.15,time);g.gain.exponentialRampToValueAtTime(.0001,time+.045);o.connect(g);g.connect(master);o.start(time);o.stop(time+.05);o.onended=()=>g.disconnect();tones.set('tick-'+time,{gain:g,nodes:[o]});o.onended=()=>{tones.delete('tick-'+time);g.disconnect()}}
  function activity(){if(session)session.last=performance.now()}
  function feedback(text,error=false){const box=$('#feedback');if(box){box.classList.toggle('error',error);box.innerHTML=`<strong>${esc(text)}</strong><small>${session?`${session.matches.length} / ${session.total} 音`:'触屏练习'}</small>`}}
  function keyPress(note,source){
    if(!held.has(note))held.set(note,new Set());const set=held.get(note);if(set.has(source))return;const fresh=!set.size;set.add(source);
    document.querySelector(`.key[data-note="${note}"]`)?.classList.add('pressed');
    ensureAudio().then(()=>{if(held.get(note)?.has(source))sound(note,audio.currentTime,8,source)}).catch(()=>{});
    activity();if(!session||!fresh||session.done)return;
    const beat=(audio.currentTime-session.start)*state.bpm/60;
    if(mode==='rhythm'&&beat<0){feedback('预备拍…听四拍后开始');return}
    const at=Math.max(0,audio.currentTime-session.captureStart),capture={note,at,duration:0,index:session.index,source};
    if(at<=300&&session.capture.length<600)session.capture.push(capture);
    session.actual.push({note,beat});
    if(mode==='wait'){
      const e=session.expected[session.index];if(!e)return;
      if(!e.notes.length){session.mistakes.add(session.index);feedback('休止符0：这一拍不要按键',true);return}if(!e.notes.includes(note)){session.mistakes.add(session.index);feedback(`试试 ${e.notes.map(n=>N.label(n,state.notation)).join(' + ')}，刚才是 ${C.name(note)}`,true);return}
      session.group.add(note);
      if(e.notes.every(n=>held.has(n)&&session.group.has(n))){
        e.notes.forEach((n,j)=>session.matches.push({key:e.index+':'+j,index:e.index,note:n,delta:0}));session.index++;session.group.clear();feedback('正确，继续下一组');updateScore();
        if(session.index>=session.expected.length)finish(true);
      }else feedback('保持已按住的音，再按和弦中的其余音');
    }else{
      const m=C.matchRhythm(session.expected,session.matched,note,beat);
      if(m){capture.index=m.index;if(Math.abs(m.delta)>.18)session.mistakes.add(m.index);session.matches.push(m);session.matched.add(m.key);const ms=Math.round(Math.abs(m.delta)*60/state.bpm*1000);feedback(Math.abs(m.delta)<=.18?'音高与起音节奏准确':`${m.delta<0?'略早':'略晚'} ${ms} 毫秒`);updateScore()}
      else {session.mistakes.add(session.index);feedback(`这个时刻不需要 ${C.name(note)}，继续跟拍`,true);}
    }
  }
  function keyRelease(note,source){if(session){const n=session.capture.findLastIndex(n=>n.source===source&&!n.closed);if(n>=0){const item=session.capture[n];item.duration=Math.min(8,300-item.at,Math.max(.04,audio.currentTime-session.captureStart-item.at));item.closed=true}}else closeTail(source);const set=held.get(note);if(!set)return;set.delete(source);releaseSound(source);if(!set.size){held.delete(note);document.querySelector(`.key[data-note="${note}"]`)?.classList.remove('pressed')}}
  function totalMinutes(){return Math.round(state.history.reduce((s,h)=>s+h.seconds,0)/60)}
  function todayMinutes(){return Math.floor(state.history.filter(h=>h.date===day()).reduce((s,h)=>s+h.seconds,0)/60)}
  function nextLesson(){return D.learningOrder.find(i=>!state.completed.includes(i))??-1}
  const nav=[['home','◷','今日'],['courses','▤','课程'],['songs','♫','曲目'],['theory','♮','乐理'],['progress','▥','成长'],['settings','⚙','设置']];
  function shell(content){$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div><div class="brand"><span>♮</span>琴阶</div><div class="brand-sub">每天一点音乐</div></div><nav class="nav">${nav.map(([id,icon,name])=>`<button data-nav="${id}" class="${route===id||(route==='lesson'&&id==='courses')||(route==='song-import'&&id==='songs')?'active':''}"><span class="nav-icon">${icon}</span>${name}</button>`).join('')}</nav><div class="side-note">一块屏幕，一段旋律。<br>按自己的节奏来。</div></aside><main class="main"><div class="topline"><span>${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span><span class="tag"><i class="dot"></i>离线 · 触屏版 1.4</span></div>${content}</main></div>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));bindActions()}
  function go(where){if(session)finish(false);stopDemo();exitGuide(false);silence();route=where;if(where!=='song-import')pendingSongs=null;result=null;render();window.scrollTo(0,0)}
  function render(){if(route==='home')home();else if(route==='courses')courses();else if(route==='lesson')readLesson();else if(route==='songs')songs();else if(route==='song-import')songImportPreview();else if(route==='practice')practice();else if(route==='theory')theory();else if(route==='progress')progress();else settings()}
  function home(){const next=nextLesson(),i=next<0?0:next,percent=Math.min(100,Math.round(todayMinutes()/state.minutes*100));shell(`
    <div class="hero"><div><div class="eyebrow">YOUR DAILY MUSIC</div><h1>慢慢来，<br>今天也弹一点。</h1><p>不需要电钢琴。轻触屏幕，从一个音开始。</p><button data-practice="${D.lessons[i].exercise}">开始今天的练习 →</button></div><div class="mini-piano" aria-hidden="true">${Array.from({length:7},()=>'<i></i>').join('')}<b style="left:10%"></b><b style="left:25%"></b><b style="left:54%"></b><b style="left:69%"></b><b style="left:83%"></b></div></div>
    <div class="callout learning-intro"><b>会简谱，也能开始。</b>先用1=C找回熟悉的数字，再在对照谱中慢慢认识五线谱。<div class="row" style="margin-top:12px"><button class="small outline" data-lesson="16">从简谱开始</button><button class="small outline" data-lesson="19">看简谱与五线谱对照</button></div></div><div class="stats"><div class="stat"><span>今天已练</span><strong>${todayMinutes()}<small> / ${state.minutes} 分钟</small></strong><div class="progress"><div style="width:${percent}%"></div></div></div><div class="stat"><span>累计练习</span><strong>${totalMinutes()}<small> 分钟</small></strong><span>从每一次轻触积累</span></div><div class="stat"><span>课程学习</span><strong>${state.completed.length}<small> / ${D.lessons.length}</small></strong><span>理解后再往前走</span></div></div>
    <div class="grid"><div class="card"><div class="row between"><h2>今天的小计划</h2><span class="tag">${state.minutes}分钟</span></div>${[['♮','键盘热身','五个白键，先慢慢找音',Math.max(1,Math.round(state.minutes*.15)),0],['▤','继续学习',D.lessons[i].title,Math.max(1,Math.round(state.minutes*.25)),'lesson'],['♫','旋律练习','听示范，再自己试一次',Math.max(1,Math.round(state.minutes*.45)),12],['◷','回顾一下','看看准确率与下次练习方向',Math.max(1,state.minutes-Math.max(1,Math.round(state.minutes*.15))-Math.max(1,Math.round(state.minutes*.25))-Math.max(1,Math.round(state.minutes*.45))),'progress']].map(([icon,title,sub,min,target])=>`<div class="task"><span class="task-icon">${icon}</span><div class="task-text"><b>${title}</b><small>${esc(sub)} · 建议${min}分钟</small></div><button class="small outline" ${target==='lesson'?`data-lesson="${i}"`:target==='progress'?'data-action="progress"':`data-practice="${target}"`}>开始</button></div>`).join('')}</div>
    <div class="card"><div class="eyebrow">MY NEXT STEP</div><h2>你的学习目标</h2><p>${esc(state.goal)}</p><div class="callout">${next<0?'你已经浏览完全部课程。试着隐藏提示，复习熟悉的曲目。':`下一课：${D.lessons[i].title}<br>先学会一个小技能，再把它放进音乐里。`}</div><button class="outline" data-action="settings">调整目标</button><p class="audio-note">第一次弹奏会启动声音。横屏时琴键更宽，平板上更容易同时按多个音。</p></div></div>`)}
  function courses(){shell(`<div class="eyebrow">LEARNING PATH</div><h1>从第一个音开始</h1><p class="muted">28节课，六个阶段。先从简谱开始；每课都有例子、练习步骤、易错点与两道理解题。</p>${D.stages.map((s,stage)=>`<div class="section-title"><h2><small>0${stage+1} / </small>${s}</h2><small>${D.lessons.filter((l,i)=>l.stage===stage&&state.completed.includes(i)).length} / ${D.lessons.filter(l=>l.stage===stage).length} 已学习</small></div><div class="lesson-grid">${D.learningOrder.map(i=>{const l=D.lessons[i];return l.stage===stage?`<article class="card lesson-card"><span class="badge ${state.completed.includes(i)?'done':''}">${state.completed.includes(i)?'已学习 · 可复习':'可开始'}</span><h3>${l.title}</h3><p>${l.desc}</p><button class="small outline" data-lesson="${i}">进入课程 →</button></article>`:''}).join('')}</div>`).join('')}<p class="footer-note">“已学习”记录阅读与理解检查，不代表实体钢琴技能认证。课程可自由浏览。</p>`)}
  function readLesson(){
    const l=D.lessons[lesson],position=D.learningOrder.indexOf(lesson),example=C.events(D.exercises[l.exercise].sequence);
    const correct=state.quiz.includes(lesson)&&state.review.includes(lesson);
    const question=(q,type,done)=>`<div class="question-block"><span class="badge">${type==='quiz'?'检查1 · 理解概念':'检查2 · 用到例子里'}</span><h3>${q.question}</h3><div class="quiz-options">${q.options.map((o,i)=>`<button data-${type}="${i}">${o}</button>`).join('')}</div><div id="${type}-feedback" role="status">${done?'<p class="muted">已答对。需要时可以再做一遍。</p>':''}</div></div>`;
    shell(`<div class="reading"><button class="small outline" data-action="courses">← 全部课程</button><div style="margin-top:25px" class="eyebrow">${D.stages[l.stage]} / 学习路线第${position+1}课</div><h1>${l.title}</h1><div class="callout"><b>这节学会什么：</b>${l.desc}</div>
      <div class="card"><h2>一步一步理解</h2><ol>${l.points.map(p=>`<li>${p}</li>`).join('')}</ol><div class="callout">${l.tip}</div></div>
      <div class="card"><div class="row between"><h2>看一个具体例子</h2>${notationSelect('lesson-notation')}</div><h3>${l.worked.title}</h3><p>${l.worked.text}</p><div id="worked-score" class="score-scroll lesson-score">${N.render(example,{notation:state.notation,meter:D.exercises[l.exercise].meter||4,hints:true})}</div><p class="audio-note">简谱以1=C为参考，无点1对应中央C。两种谱展示相同音高与时值；不熟悉时先选对照。</p><button data-demo="${l.exercise}" class="outline">♫ 听例子示范</button></div>
      ${l.stage===0?pitchBridge():''}
      <div class="card"><h2>跟着做，别急着求快</h2><ol>${l.steps.map(s=>`<li>${s}。</li>`).join('')}</ol><div class="row"><button class="primary" data-guided="${l.exercise}">老师带我练 →</button><button class="outline" data-practice="${l.exercise}">自己练习</button></div></div>
      <div class="card"><h2>常见误区</h2><p class="mistake"><b>容易误解：</b>${l.pitfall.wrong}</p><p><b>应该这样理解：</b>${l.pitfall.correct}</p></div>
      <div class="card"><h2>确认自己懂了</h2>${question(l,'quiz',state.quiz.includes(lesson))}${question(l.reviewQuestion,'review-quiz',state.review.includes(lesson))}<button id="complete-lesson" class="primary" ${correct?'':'disabled'}>标记已学习</button><p class="audio-note">两道题答对后可以标记。建议也完成一次触屏练习；隔日再做一次，看看是否仍记得。</p></div>
      <div class="row between"><button class="outline" id="prev-lesson" ${position===0?'disabled':''}>← 上一课</button><button class="outline" id="next-lesson" ${position===D.learningOrder.length-1?'disabled':''}>下一课 →</button></div></div>`);
    function bindQuestion(selector,q,store,target){document.querySelectorAll(selector).forEach(b=>b.onclick=()=>{const answer=Number(b.getAttribute(selector==='[data-quiz]'?'data-quiz':'data-review-quiz')),right=answer===q.answer;$(target).innerHTML=`<p class="answer-explanation ${right?'correct':'retry'}"><b>${right?'答对了。':'再想想。'}</b>${q.explanation||l.answerExplanation}</p>`;if(right&&!state[store].includes(lesson)){state[store].push(lesson);save()}$('#complete-lesson').disabled=!(state.quiz.includes(lesson)&&state.review.includes(lesson))})}
    bindQuestion('[data-quiz]',l,'quiz','#quiz-feedback');bindQuestion('[data-review-quiz]',l.reviewQuestion,'review','#review-quiz-feedback');
    $('#complete-lesson').onclick=()=>{if(!state.completed.includes(lesson))state.completed.push(lesson);save();toast('已记录。隔一两天再练一次，看看是否还记得。')};
    $('#prev-lesson').onclick=()=>{stopDemo();lesson=D.learningOrder[position-1];render();window.scrollTo(0,0)};
    $('#next-lesson').onclick=()=>{stopDemo();lesson=D.learningOrder[position+1];render();window.scrollTo(0,0)};
    $('#lesson-notation').onchange=e=>{state.notation=e.target.value;save();$('#worked-score').innerHTML=N.render(example,{notation:state.notation,meter:D.exercises[l.exercise].meter||4,hints:true})};
    document.querySelectorAll('[data-tone]').forEach(b=>b.onclick=async()=>{stopDemo();silence();try{await ensureAudio();sound(Number(b.dataset.tone),audio.currentTime,.7,'bridge-tone')}catch(e){}});
  }

  function songCards(){
    const ids=D.exercises.map((e,i)=>i).filter(i=>{const e=D.exercises[i];return (filter<0||(e.tier??e.level)===filter)&&(songKind==='all'||songKind==='mine'&&e.custom||songKind==='full'&&e.complete||songKind==='exercise'&&!e.complete)&&(!songQuery||[e.title,e.desc,...(e.skills||[])].join(' ').toLowerCase().includes(songQuery.toLowerCase()))}).sort((a,b)=>Number(Boolean(D.exercises[b].complete))-Number(Boolean(D.exercises[a].complete))||(D.exercises[a].tier??D.exercises[a].level)-(D.exercises[b].tier??D.exercises[b].level)||a-b);
    return ids.length?ids.map(i=>{const e=D.exercises[i],tier=e.tier??e.level,bars=C.measures(e.sequence,e.meter||4);return `<article class="card lesson-card song-card" data-song-id="${i}"><span class="badge">${['起步','基础','提升','挑战'][tier]} · ${e.complete?e.version:'专项／片段'}${e.custom?' · 我的曲库':''}</span><h3>${esc(e.title)}</h3><small>${bars}小节 · ${e.meter||4}/4拍${e.bpm?' · 建议'+e.bpm+' BPM':''}${e.custom?' · 第'+e.revision+'版':''}</small><p>${esc(e.desc)}</p>${e.complete||e.custom?`<div class="song-skills">${e.skills.map(t=>`<span>${esc(t)}</span>`).join('')}</div><details><summary>结构与练法</summary><p>${esc(e.form)}</p><ol>${e.plan.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><small>${esc(e.source)}</small></details>`:''}<div class="row"><button class="small outline" data-demo="${i}">试听</button><button class="small primary" data-practice="${i}">练习 →</button>${e.complete||e.custom?`<button class="small outline" data-guided="${i}">带我练</button>`:''}</div>${e.custom?`<button class="small remove-song" data-remove-song="${esc(e.id)}">移除这首</button>`:''}</article>`}).join(''):'<div class="card empty">没有找到对应曲目，试着减少筛选条件，或导入你的歌曲包。</div>';
  }
  function songs(){shell(`<div class="eyebrow">A SONG FROM START TO FINISH</div><h1>从头到尾，弹完一首歌</h1><p class="muted">内置11首完整旋律与2个双音版。想弹更多歌，可以导入定制歌曲包，按自己的节奏扩充曲库。</p><div class="song-path">少量白键 → 半拍与乐句 → 弱起与完整结构 → 变化音／双音</div><section class="library-tools"><div><b>我的曲库 · ${library.songs.length}首</b><small>导入前先预览；同ID更新版本，学习记录保留。</small></div><div class="row"><button id="import-songs" class="small primary">＋ 导入歌曲</button><button id="export-songs" class="small outline" ${library.songs.length?'':'disabled'}>导出我的曲库</button><button id="song-help" class="small outline">导入说明</button></div></section>${libraryNotice?`<div class="callout import-error" role="alert">${esc(libraryNotice)}</div>`:''}<details id="import-help" class="card import-help"><summary>定制歌曲怎么导入？</summary><ol><li>把《歌曲定制与导入规则.md》交给我，并提供歌名、具体版本或乐谱。</li><li>我按规则生成.qinjie.json歌曲包；一份可装一首或多首歌。</li><li>把文件存到平板，点“导入歌曲”，预览后确认。</li><li>在“我的曲库”中试听、切换谱式、分段跟练；以后更新同ID，或导出备份。</li></ol><p>当前支持音符JSON，不直接读取音频、图片、MIDI或MusicXML。最多200首自定义歌曲，单文件2MB。遇到格式错误会说明位置，整包取消导入。</p></details><div class="row catalog-tools"><label>找曲目 <input id="song-search" type="search" placeholder="搜歌名或技能，如附点" value="${esc(songQuery)}"></label><span id="song-count" class="tag">内置39项 · 我的曲库${library.songs.length}首</span></div><div class="tabs"><span class="filter-label">内容</span>${[['all','全部'],['full','完整曲'],['exercise','专项／片段'],['mine','我的曲库']].map(([id,t])=>`<button data-kind="${id}" class="${songKind===id?'active':''}">${t}</button>`).join('')}</div><div class="tabs"><span class="filter-label">难度</span>${[[-1,'全部'],[0,'起步'],[1,'基础'],[2,'提升'],[3,'挑战']].map(([i,t])=>`<button data-filter="${i}" class="${filter===i?'active':''}">${t}</button>`).join('')}</div><div id="song-list" class="lesson-grid">${songCards()}</div><p class="footer-note">完整曲展示本版全部旋律与结尾；传统歌曲演奏一轮，《欢乐颂》为完整主题。双音版保留完整旋律并加入简化伴奏。导入歌曲以文件标注的编排范围为准。</p><input id="song-file" type="file" accept="application/json,.json" hidden>`);
    document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{stopDemo();filter=Number(b.dataset.filter);songs()});document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{stopDemo();songKind=b.dataset.kind;songs()});$('#song-search').oninput=e=>{stopDemo();songQuery=e.target.value;$('#song-list').innerHTML=songCards();bindActions();bindRemoveSongs()};
    $('#import-songs').onclick=()=>{stopDemo();if(window.Android&&Android.importSongs)Android.importSongs();else $('#song-file').click()};$('#song-file').onchange=async e=>{const f=e.target.files[0];if(f&&f.size<=L.MAX_BYTES)window.importPianoSongs(await f.text());else{libraryNotice='歌曲文件最大2MB，请拆成多个歌曲包。';songs()}};
    $('#export-songs').onclick=()=>exportFile(JSON.stringify(library,null,2),'琴阶曲库-'+day()+'.qinjie.json','songs');$('#song-help').onclick=()=>{$('#import-help').open=!$('#import-help').open};bindRemoveSongs();
  }
  function bindRemoveSongs(){document.querySelectorAll('[data-remove-song]').forEach(b=>b.onclick=()=>{const id=b.dataset.removeSong,s=library.songs.find(s=>'custom:'+s.id===id);if(!s||!confirm('移除“'+s.title+'”？已有学习记录保留；重新导入同ID后可再次打开关联回放。'))return;stopDemo();const pack={...library,songs:library.songs.filter(x=>x.id!==s.id)};if(storeLibrary(pack)){libraryNotice='已移除这首，练习记录保留。';songs()}})}
  window.importPianoSongs=raw=>{if(session)finish(false);stopDemo();exitGuide(false);silence();try{const incoming=L.parse(raw);L.merge(library,incoming);pendingSongs=incoming;route='song-import';libraryNotice='';songImportPreview();window.scrollTo(0,0)}catch(e){pendingSongs=null;libraryNotice='导入未完成，原曲库保留。'+e.message;route='songs';songs()}};
  function songImportPreview(){if(!pendingSongs){go('songs');return}const incoming=pendingSongs.songs,updates=incoming.filter(s=>library.songs.some(x=>x.id===s.id));shell(`<div class="eyebrow">YOUR SONGS</div><h1>确认这份歌曲包</h1><p class="muted">新增${incoming.length-updates.length}首，更新${updates.length}首。确认后保存到平板，已有学习记录保留。</p><div class="callout">同ID更新会替换原曲谱与教学说明；过去演奏回放仍保留当时的音符。</div><div class="card import-preview">${incoming.map(s=>{const old=library.songs.find(x=>x.id===s.id);return `<article><span class="badge">${old?'更新 第'+old.revision+'版 → 第'+s.revision+'版':'新增'} · ${s.complete?'完整编排':'片段'}</span><h3>${esc(s.title)}</h3><small>${esc(s.composer)} · ${C.measures(s.sequence,s.meter)}小节 · ${s.meter}/4 · ${s.bpm} BPM · ${['起步','基础','提升','挑战'][s.level]}</small><p>${esc(s.form)}</p><small>${esc(s.source)}</small></article>`}).join('')}</div><div class="row"><button class="primary" id="confirm-song-import">确认导入${incoming.length}首</button><button class="outline" data-action="songs">取消</button></div>`);$('#confirm-song-import').onclick=()=>{try{const next=L.merge(library,pendingSongs);if(!storeLibrary(next))return;songKind='mine';filter=-1;songQuery='';pendingSongs=null;libraryNotice='导入完成：新增'+(incoming.length-updates.length)+'首，更新'+updates.length+'首。';go('songs')}catch(e){toast('未导入：'+e.message)}}}
  function exportFile(raw,name,kind){if(window.Android){if(kind==='songs'&&Android.exportSongs){Android.exportSongs(raw);return}if(kind==='records'&&Android.exportData){Android.exportData(raw);return}}const a=document.createElement('a'),url=URL.createObjectURL(new Blob([raw],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

  function notationSelect(id){return `<label class="notation-control">谱式 <select id="${id}">${[['numbered','简谱'],['staff','五线谱'],['both','对照显示']].map(([value,text])=>`<option value="${value}" ${state.notation===value?'selected':''}>${text}</option>`).join('')}</select></label>`}
  function pitchBridge(){return `<div class="card"><h2>你熟悉的简谱，对应到哪里？</h2><p>先用1=C。点音名按钮能听这个音，不用一次背完。</p><div class="table-scroll"><table class="bridge-table"><thead><tr><th>简谱</th><th>唱名</th><th>音名 · 点击试听</th><th>高音谱表位置</th></tr></thead><tbody>${[60,62,64,65,67,69,71,72].map((n,i)=>`<tr><td class="bridge-number">${i===7?'1̇':i+1}</td><td>${['do','re','mi','fa','sol','la','si','do'][i]}</td><td><button class="small outline" data-tone="${n}">${C.name(n)} ♫</button></td><td>${['下方第一条加线','下加线与第一线之间','第一线','第一间','第二线','第二间','第三线','第三间'][i]}</td></tr>`).join('')}</tbody></table></div></div>`}
  function exerciseEvents(){const e=D.exercises[selected],original=e.sequence,cut=Math.ceil(original.length/2);if(range==='bars')return C.sliceMeasures(original,e.meter||4,barFirst,barLast);return C.events(range==='first'?original.slice(0,cut):range==='second'?original.slice(cut):original)}
  function rangeTitle(){return range==='all'?'全部':range==='first'?'前半段':range==='second'?'后半段':`第${barFirst}—${barLast}小节`}
  function keyboardBounds(){
    const notes=exerciseEvents().flatMap(e=>e.notes),low=notes.length?Math.min(...notes):60,high=notes.length?Math.max(...notes):67,isBlack=n=>[1,3,6,8,10].includes(n%12);
    let base=Math.floor(low/12)*12;const wide=state.keyboard==='wide'&&high<=base+12;
    if(!wide&&high>base+23){base=low;while(isBlack(base))base--}
    let end=base+(wide?12:23);end=Math.max(end,high);while(isBlack(end))end++;
    let white=0;for(let n=base;n<=end;n++)if(!isBlack(n))white++;
    return {base:base+octave*12,end:end+octave*12,white,wide};
  }

  function guidePanel(){if(!guide)return `<div class="guide-invite"><span>听一段，跟着弹，再独立试一次。</span><button class="small primary" id="guide-start">老师带我练</button></div>`;const step=guide.stage==='listen'?0:guide.stage==='follow'?1:2;return `<section class="guide-panel"><div class="row between"><div class="guide-steps">${['① 听示范','② 带提示练','③ 独立试'].map((t,i)=>`<span class="${step===i?'current':''}">${t}</span>`).join('')}</div><button class="small outline" id="guide-exit">退出跟练</button></div><p id="guide-message">${guide.stage==='listen'?'先听这一段，观察数字与琴键；听完进入跟练。':guide.stage==='follow'?'按提示慢慢找音，弹错时停下来重试。':'提示已隐藏，听四拍预备后独立跟拍；困难时可以重听。'} <b>${rangeTitle()}</b></p></section>`}
  function beginGuide(){if(session||demo)return;const old={hints:state.hints,mode,range,barFirst,barLast};const e=D.exercises[selected],count=C.measures(e.sequence,e.meter||4);if(range!=='bars'){barFirst=range==='second'?Math.floor(count/2)+1:1;barLast=range==='first'?Math.ceil(count/2):Math.min(count,barFirst+1);range='bars'}guide={stage:'listen',old};state.hints=true;mode='wait';result=null;practice()}
  function exitGuide(redraw=true){if(!guide)return;if(session)finish(false);stopDemo();state.hints=guide.old.hints;mode=guide.old.mode;range=guide.old.range;barFirst=guide.old.barFirst;barLast=guide.old.barLast;guide=null;save();if(redraw){result=null;practice()}}
  async function guideAction(){if(!guide||session||demo)return;if(guide.stage==='listen'){await playDemo(selected);return}await start()}
  function guideAfterDemo(){if(!guide||guide.stage!=='listen')return;guide.stage='follow';state.hints=true;mode='wait';practice()}
  function guideAdvance(){if(!guide)return;stopDemo();silence();if(guide.stage==='follow'){guide.stage='independent';state.hints=false;mode='rhythm';result=null;practice();return}const count=C.measures(D.exercises[selected].sequence,D.exercises[selected].meter||4);if(barLast>=count){exitGuide();toast('这一首的跟练完成了，可以再完整弹一遍。');return}barFirst=barLast+1;barLast=Math.min(count,barFirst+1);guide.stage='listen';state.hints=true;mode='wait';result=null;practice()}
  function rangeOptions(){const count=C.measures(D.exercises[selected].sequence,D.exercises[selected].meter||4),options=(value)=>Array.from({length:count},(_,i)=>`<option value="${i+1}" ${value===i+1?'selected':''}>${i+1}</option>`).join('');return `<label>选段 <select id="range"><option value="all" ${range==='all'?'selected':''}>全部</option><option value="bars" ${range==='bars'?'selected':''}>指定小节</option><option value="first" ${range==='first'?'selected':''}>前半段</option><option value="second" ${range==='second'?'selected':''}>后半段</option></select></label>${range==='bars'?`<label>第 <select id="bar-first">${options(barFirst)}</select> 至 <select id="bar-last">${options(barLast)}</select> 小节</label>`:''}`}

  function scoreSVG(expected){return N.render(expected,{notation:state.notation,meter:demo?.meter||D.exercises[selected].meter||4,hints:state.hints})}
  function setCursor(index){document.querySelectorAll('[data-score-index]').forEach(g=>g.querySelector('.cursor')?.setAttribute('opacity',Number(g.dataset.scoreIndex)===index?'1':'0'))}
  function scoreTitle(){return `${state.notation==='numbered'?'简谱 · 1=C':state.notation==='staff'?'五线谱 · 高音谱表':'简谱／五线谱对照 · 1=C'} · ${demo?.meter||D.exercises[selected].meter||4}/4拍`}
  function changeNotation(notation){
    state.notation=notation;save();$('.score-scroll').innerHTML=scoreSVG(session?.expected||exerciseEvents());$('#score-title').textContent=scoreTitle();
    $('.main').classList.toggle('compare-mode',notation==='both');
    document.querySelectorAll('.key').forEach(k=>k.querySelector('span').innerHTML=N.keyLabel(Number(k.dataset.note),state.notation,state.hints));
    $('#notation-help').textContent=notationHelp();if(session)session.scroll=-1;updateScore();
  }
  function notationHelp(){return state.notation==='staff'?'看不懂位置时，切到对照显示，先认中央C、E、G。':state.notation==='both'?'上下是同一组音，按键时同步高亮。先看数字，再看五线谱位置。':'无点1=C4；上／下点表示八度，后横线延长，下划线缩短，0是休止。'}

  function keyboard(){const whites=[],blacks=[],b=keyboardBounds();let wi=0;for(let n=b.base;n<=b.end;n++){if([1,3,6,8,10].includes(n%12)){const width=67/b.white;blacks.push(`<button class="key black" data-note="${n}" style="width:${width}%;left:calc(${wi/b.white*100}% - ${width/2}%)" aria-label="${C.name(n)}"><span>${N.keyLabel(n,state.notation,state.hints)}</span></button>`)}else{whites.push(`<button class="key white" data-note="${n}" aria-label="${C.name(n)}"><span>${N.keyLabel(n,state.notation,state.hints)}</span></button>`);wi++}}return whites.join('')+blacks.join('')}

  function practice(){
    const e=D.exercises[selected],expected=exerciseEvents();
    shell(`<div class="practice-head"><div><div class="eyebrow">TOUCH & PLAY</div><h1>${esc(e.title)}</h1><small>${esc(e.desc)}</small></div><button class="small outline" data-action="songs">换一首</button></div>
      ${guidePanel()}${e.complete||e.custom?`<details class="piece-plan"><summary>这首怎样练 · ${e.version} · 建议${e.bpm} BPM</summary><p>${esc(e.form)}</p><ol>${e.plan.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><button id="song-speed" class="small outline">使用建议速度 ${e.bpm} BPM</button></details>`:''}<div class="practice-options"><label>模式 <select id="mode"><option value="wait" ${mode==='wait'?'selected':''}>找音 · 弹对再前进</option><option value="rhythm" ${mode==='rhythm'?'selected':''}>节奏 · 跟拍弹奏</option></select></label>${notationSelect('notation')}<label>速度 <input id="bpm" type="range" min="35" max="120" value="${state.bpm}"><b id="bpm-label">${state.bpm}</b> BPM</label>${rangeOptions()}<label><input id="hints" type="checkbox" ${state.hints?'checked':''}>提示</label></div>
      <div class="score-panel"><div class="row between"><span id="score-title" class="tag">${scoreTitle()}</span><small id="practice-status">${mode==='wait'?'慢慢找对每一个音':'开始后有四拍预备拍'}</small></div><div class="score-scroll">${scoreSVG(expected)}</div><div id="feedback" class="feedback" role="status"><strong>先听示范，或直接开始练习</strong><small>触屏练习</small></div></div>
      <p id="notation-help" class="notation-help">${notationHelp()}</p>
      <div class="keyboard-wrap"><div class="keyboard-toolbar"><label>键盘 <select id="keyboard-layout"><option value="wide" ${state.keyboard==='wide'?'selected':''}>大键入门</option><option value="full" ${state.keyboard==='full'?'selected':''}>双八度</option></select></label><span class="keyboard-caption">${state.keyboard==='wide'&&!keyboardBounds().wide?'音域较宽，自动展示双八度':'轻触发声 · 多指可同时弹奏'}</span><div class="row"><button id="octave-down" class="small outline" aria-label="降低一个八度">− 八度</button><span>${C.name(keyboardBounds().base)}—${C.name(keyboardBounds().end)}</span><button id="octave-up" class="small outline" aria-label="升高一个八度">＋ 八度</button></div></div><div class="keyboard" id="keyboard">${keyboard()}</div></div>
      <div class="transport"><button id="demo-btn" class="outline">♫ ${demo?'停止示范':'听示范'}</button><button id="start-btn" class="primary">${guide?guide.stage==='listen'?'播放跟练示范 →':guide.stage==='follow'?'开始带提示练习 →':'开始独立试奏 →':'开始练习 →'}</button><button id="finish-btn" class="outline" disabled>结束并记录</button><button id="free-btn" class="outline">自由弹奏</button><label class="repeat-control"><input id="repeat" type="checkbox" ${state.repeat?'checked':''}>循环练习</label></div>
      <p class="practice-tip">${mode==='wait'?'和弦同时保持目标音；重复音松开再按；休止符按当前速度等待。':'四拍预备后开始；0时不要按键，起音反馈不检查保持时长。'}${range==='all'?'':'选段从第1拍重新计数。'}<br>合成琴音 · 指法与力度不自动评分</p><div id="result"></div>`);
    $('.main').classList.toggle('compare-mode',state.notation==='both');
    $('#notation').onchange=e=>changeNotation(e.target.value);if($('#song-speed'))$('#song-speed').onclick=()=>{state.bpm=e.bpm;save();practice()};
    $('#range').onchange=e=>{stopDemo();range=e.target.value;if(range==='bars'){barFirst=1;barLast=Math.min(2,C.measures(D.exercises[selected].sequence,D.exercises[selected].meter||4))}result=null;practice()};
    if($('#bar-first'))$('#bar-first').onchange=e=>{barFirst=Number(e.target.value);barLast=Math.max(barFirst,barLast);result=null;practice()};
    if($('#bar-last'))$('#bar-last').onchange=e=>{barLast=Number(e.target.value);barFirst=Math.min(barFirst,barLast);result=null;practice()};
    $('#keyboard-layout').onchange=e=>{silence();state.keyboard=e.target.value;octave=0;save();practice()};
    $('#repeat').onchange=e=>{state.repeat=e.target.checked;save()};
    if($('#guide-start'))$('#guide-start').onclick=beginGuide;if($('#guide-exit'))$('#guide-exit').onclick=()=>exitGuide();if($('#guide-action'))$('#guide-action').onclick=guideAction;
    $('#mode').onchange=e=>{stopDemo();mode=e.target.value;result=null;practice()};
    $('#bpm').oninput=e=>{state.bpm=Number(e.target.value);$('#bpm-label').textContent=state.bpm;save()};
    $('#hints').onchange=e=>{state.hints=e.target.checked;save();stopDemo();practice()};
    $('#octave-down').onclick=()=>changeOctave(-1);$('#octave-up').onclick=()=>changeOctave(1);
    $('#demo-btn').onclick=()=>demo?stopDemo():playDemo(selected);$('#start-btn').onclick=()=>guide?guideAction():start();$('#finish-btn').onclick=()=>{if(session)finish(false);else{state.repeat=false;$('#repeat').checked=false;save();$('#finish-btn').disabled=true;feedback('循环已停止')}};
    $('#free-btn').onclick=()=>{if(session)finish(false);stopDemo();if(guide)exitGuide();state.repeat=false;save();$('#repeat').checked=false;result=null;$('#result').innerHTML='';$('#finish-btn').disabled=true;feedback('自由弹奏：触碰琴键即可发声，不计入课程成绩')};
    attachKeyboard();if(result)showResult();updateScore();if(guide){['mode','range','bar-first','bar-last','hints','repeat'].forEach(id=>{if($('#'+id))$('#'+id).disabled=true})}
  }

  function changeOctave(d){if(session||demo)return;silence();octave=Math.max(-1,Math.min(1,octave+d));practice()}
  function attachKeyboard(){const k=$('#keyboard');k.addEventListener('pointerdown',e=>{const key=e.target.closest('.key');if(!key)return;e.preventDefault();const n=Number(key.dataset.note),src='p'+e.pointerId;pointers.set(e.pointerId,n);k.setPointerCapture(e.pointerId);keyPress(n,src)});k.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;const key=document.elementFromPoint(e.clientX,e.clientY)?.closest('.key'),old=pointers.get(e.pointerId),n=key?Number(key.dataset.note):null;if(n===old)return;if(old!==null)keyRelease(old,'p'+e.pointerId);pointers.set(e.pointerId,n);if(n!==null)keyPress(n,'p'+e.pointerId)});const end=e=>{if(pointers.has(e.pointerId)){const n=pointers.get(e.pointerId);if(n!==null)keyRelease(n,'p'+e.pointerId);pointers.delete(e.pointerId)}};k.addEventListener('pointerup',end);k.addEventListener('pointercancel',end);k.addEventListener('lostpointercapture',end)}
  function lockControls(locked){['mode','range','bar-first','bar-last','bpm','hints','keyboard-layout','repeat','octave-down','octave-up','start-btn','demo-btn','guide-start','guide-action','replay-mine','replay-model','song-speed','guide-next','guide-retry'].forEach(id=>{const e=$('#'+id);if(e)e.disabled=locked});if($('#finish-btn'))$('#finish-btn').disabled=!locked;if(guide&&!locked)['mode','range','bar-first','bar-last','hints','repeat'].forEach(id=>{if($('#'+id))$('#'+id).disabled=true})}
  async function start(){if(session||demo||(!guide&&$('#start-btn').disabled))return;stopDemo();silence();$('#start-btn').disabled=true;try{await ensureAudio()}catch(e){$('#start-btn').disabled=false;return}result=null;$('#result').innerHTML='';const expected=exerciseEvents(),total=expected.reduce((s,e)=>s+e.notes.length,0),now=performance.now();session={expected,total,index:0,group:new Set(),matches:[],actual:[],matched:new Set(),start:audio.currentTime+(mode==='rhythm'?4*60/state.bpm:0),last:now,frame:now,seconds:0,done:false,scroll:-1,restEnd:null,captureStart:audio.currentTime+(mode==='rhythm'?4*60/state.bpm:0),capture:[],mistakes:new Set()};octave=0;if($('#keyboard'))$('#keyboard').innerHTML=keyboard();$('.score-scroll').innerHTML=scoreSVG(expected);lockControls(true);feedback(mode==='rhythm'?'预备拍…听四拍后开始':'开始了，找到第一个音');if(mode==='rhythm'){const end=expected.at(-1).beat+expected.at(-1).duration;for(let b=-4;b<end;b++)tick(session.start+b*60/state.bpm,b<0?b===-4:b%(D.exercises[selected].meter||4)===0)}updateScore();loop()}
  function loop(){
    if(!session)return;const now=performance.now();if(now-session.last<3000)session.seconds+=Math.min(.25,(now-session.frame)/1000);session.frame=now;
    if(mode==='rhythm'){
      const beat=(audio.currentTime-session.start)*state.bpm/60,last=session.expected.at(-1),end=last.beat+last.duration;
      if(beat>=end+.5){finish(true);return}
      session.index=beat<0?0:Math.max(0,session.expected.findLastIndex(e=>e.beat<=beat));
      $('#practice-status').textContent=beat<0?`预备 ${Math.min(4,Math.ceil(-beat))} 拍`:`第 ${session.index+1} / ${session.expected.length} 组`;
      updateScore();
    }else{
      const e=session.expected[session.index];
      if(e&&!e.notes.length){
        if(session.restEnd===null){session.restEnd=audio.currentTime+e.duration*60/state.bpm;feedback('休止：松开前音，继续数拍')}
        if(audio.currentTime>=session.restEnd){session.index++;session.restEnd=null;session.group.clear();if(session.index>=session.expected.length){finish(true);return}feedback('继续下一音');updateScore()}
      }else session.restEnd=null;
      $('#practice-status').textContent=`第 ${Math.min(session.index+1,session.expected.length)} / ${session.expected.length} 组`;
    }
    animation=requestAnimationFrame(loop);
  }
  function updateScore(){
    const expected=session?.expected||exerciseEvents(),index=session?.index??0;setCursor(index);
    document.querySelectorAll('.key.target').forEach(k=>k.classList.remove('target'));
    if(state.hints)expected[index]?.notes.forEach(n=>document.querySelector(`.key[data-note="${n}"]`)?.classList.add('target'));
    if(session){
      const count=new Map();session.matches.forEach(m=>count.set(m.index,(count.get(m.index)||0)+1));
      count.forEach((n,i)=>{if(n>=expected[i].notes.length)document.querySelectorAll(`[data-score-index="${i}"]`).forEach(g=>g.style.color='#648c53')});
      if(session.scroll!==index){session.scroll=index;const sc=$('.score-scroll');if(sc)sc.scrollLeft=Math.max(0,N.START+index*N.STEP-sc.clientWidth*.45)}
    }
  }

  function finish(complete){
    if(!session)return;cancelAnimationFrame(animation);const current=session;session=null;current.done=true;
    const elapsed=Math.max(0,audio.currentTime-current.captureStart);
    current.capture.forEach(n=>{if(!n.closed)n.duration=Math.min(8,300-n.at,Math.max(.08,elapsed-n.at+.12))});
    if(!complete)silence();else for(const id of [...tones.keys()])if(id.startsWith('tick-'))releaseSound(id);const title=D.exercises[selected].title+(range==='all'?'':' · '+rangeTitle());
    const recording=C.safeReplay({title,exercise:selected,songId:D.exercises[selected].id,meter:D.exercises[selected].meter||4,bpm:state.bpm,mode,notes:current.capture,expected:current.expected});
    if(complete&&recording)tailCapture={capture:current.capture,recording,start:current.captureStart};
    const missing=current.expected.filter(e=>e.notes.length>current.matches.filter(m=>m.index===e.index).length);missing.forEach(e=>current.mistakes.add(e.index));
    result={...C.summarize(current.expected,current.actual,current.matches,mode,state.bpm),complete,seconds:Math.round(current.seconds),recording,expected:current.expected,issue:[...current.mistakes].sort((a,b)=>a-b)[0]};
    if(current.actual.length){state.history.push({date:day(),title,seconds:result.seconds,notation:state.notation,mode,pitch:result.pitch,timing:result.timing,bpm:state.bpm});state.history=state.history.slice(-500);if(recording){state.replays.push(recording);state.replays=state.replays.slice(-5)}save()}
    lockControls(false);feedback(complete?'这一遍完成了。看看下一步怎么练。':'已结束，这一遍的弹奏记录已保存。');showResult();
    if(complete&&state.repeat&&!guide){feedback('循环间隔两秒，取消勾选或点结束可停止');$('#finish-btn').disabled=false;const token=result;setTimeout(()=>{if(route==='practice'&&result===token&&state.repeat&&!session&&!demo)start()},2000)}
  }
  function showResult(){
    const el=$('#result');if(!el||!result)return;const r=result,issue=r.expected[r.issue],where=issue?`第${Math.floor((issue.sourceBeat??issue.beat)/(D.exercises[selected].meter||4))+1}小节，第${r.issue+1}组`:'',advice=issue?`${where}需要再练。${issue.notes.length?'先听 '+issue.notes.map(n=>N.label(n,state.notation)).join(' + ')+'，再慢速试一次。':'这里是休止符，先松开按键，数清空拍。'}`:r.timing!==null&&r.timing<80?'降低5—10 BPM，听清预备拍。':'可以重听回放，检查旋律是否连贯。';
    const passed=r.complete&&r.pitch>=80&&r.precision>=80&&(r.timing===null||r.timing>=70);
    el.innerHTML=`<div class="result"><h2>${r.complete?'完成这一遍':'这次练习记录'}</h2><div class="row"><span class="note-chip">目标音命中 ${r.pitch}%</span><span class="note-chip">按键准确 ${r.precision}%</span><span class="note-chip">${r.timing===null?'找音模式 · 不评节奏':`命中音起音达标 ${r.timing}%`}</span></div><p>${r.hit}/${r.total}个目标音命中 · 漏音${r.missed}个 · 额外按键${r.extras}次 · 有效练习${r.seconds}秒</p><p><b>下一步：</b>${advice}</p>${r.recording?'<div class="row"><button id="replay-mine" class="outline small">♫ 听我的演奏</button><button id="replay-model" class="outline small">♫ 听相同片段示范</button></div>':''}${guide?`<div class="guide-result"><p>${passed?guide.stage==='follow'?'找音完成了，下一步隐藏提示，试着跟拍。':'这段已经弹稳了，可以进入下一段。':'再慢一点，重听后把这段练熟。'}</p><div class="row">${passed?`<button class="primary" id="guide-next">${guide.stage==='follow'?'进入独立试奏':'下一段／完成跟练'}</button>`:''}<button id="guide-retry" class="outline">重听这一段</button></div></div>`:''}<small>起音达标窗口：目标前后0.18拍。回放保留最近5遍，每遍最多5分钟；示范与回放不计练习时间。</small></div>`;
    if($('#replay-mine'))$('#replay-mine').onclick=()=>demo?stopDemo():playRecording(r.recording,false);
    if($('#replay-model'))$('#replay-model').onclick=()=>demo?stopDemo():playRecording(r.recording,true);
    if($('#guide-next'))$('#guide-next').onclick=guideAdvance;
    if($('#guide-retry'))$('#guide-retry').onclick=()=>{stopDemo();guide.stage='listen';state.hints=true;mode='wait';result=null;practice()};
  }
  async function playDemo(index){if(session)return;const expected=route==='practice'&&index===selected?exerciseEvents():C.events(D.exercises[index].sequence);await playAudio(expected,null,state.bpm,true)}
  async function playRecording(recording,model){if(session)return;await playAudio(recording.expected,model?null:recording.notes,recording.bpm,false,recording.meter)}
  async function playAudio(expected,notes,bpm,advance,meter=null){
    stopDemo();silence();if(route==='practice'&&state.repeat){state.repeat=false;if($('#repeat'))$('#repeat').checked=false;save()}try{await ensureAudio()}catch(e){return}const start=audio.currentTime+.15,unit=60/bpm;
    const trace=notes||expected.flatMap(e=>e.notes.map(note=>({note,at:e.beat*unit,duration:e.duration*unit*.88,index:e.index})));
    const end=notes?Math.max(...trace.map(n=>n.at+n.duration),.1):((expected.at(-1)?.beat||0)+(expected.at(-1)?.duration||1))*unit;
    trace.forEach((n,i)=>sound(n.note,start+n.at,Math.max(.04,n.duration),'demo-'+i));
    demo={expected,start,trace,end,advance,kind:notes?'mine':'model',meter};if($('#score-title'))$('#score-title').textContent=scoreTitle();$('.score-scroll')&&( $('.score-scroll').innerHTML=scoreSVG(expected));
    lockControls(true);if($('#finish-btn'))$('#finish-btn').disabled=true;if($('#demo-btn')){$('#demo-btn').disabled=false;$('#demo-btn').textContent='停止播放'}
    toast(notes?'回放你的演奏；点停止播放可结束':'示范播放中；点停止播放可结束');
    function frame(){if(!demo)return;const t=audio.currentTime-start;if(t>end+.15){stopDemo(true);return}if(route==='practice'){
      let index=notes?trace.filter(n=>n.at<=t).at(-1)?.index:Math.max(0,expected.findLastIndex(e=>e.beat*unit<=t));index=index??0;setCursor(index);
      document.querySelectorAll('.key.target,.key.replaying').forEach(k=>k.classList.remove('target','replaying'));
      trace.filter(n=>t>=n.at&&t<n.at+n.duration).forEach(n=>document.querySelector(`.key[data-note="${n.note}"]`)?.classList.add(notes?'replaying':'target'));
      const sc=$('.score-scroll');sc.scrollLeft=Math.max(0,N.START+index*N.STEP-sc.clientWidth*.45);$('#practice-status').textContent=notes?'我的演奏 · 按键与乐谱同步回放':'听示范 · 观察音符与琴键';
    }animation=requestAnimationFrame(frame)}frame();
  }
  function stopDemo(completed=false){if(!demo)return;const advance=completed&&demo.advance;demo=null;cancelAnimationFrame(animation);silence();document.querySelectorAll('.key.replaying').forEach(k=>k.classList.remove('replaying'));if($('#demo-btn'))$('#demo-btn').textContent='♫ 听示范';lockControls(false);if(route==='practice'){const expected=session?.expected||exerciseEvents();$('.score-scroll').innerHTML=scoreSVG(expected);updateScore();$('#score-title').textContent=scoreTitle();$('#practice-status').textContent='播放已结束，可以开始练习'}if(advance)guideAfterDemo()}

  function theory(){shell(`<div class="eyebrow">LISTEN, SEE, UNDERSTAND</div><h1>乐理，也可以听懂</h1><p class="muted">点一下试听，把文字与声音联系起来。</p><div class="grid">${D.theory.map((t,i)=>`<div class="card"><span class="badge">知识卡 ${i+1}</span><h2>${t.title}</h2><p>${t.text}</p><div>${(t.notes||t.chord||t.chords.flat()).map(n=>`<span class="note-chip">${C.name(n)}</span>`).join('')}</div><button class="small outline" data-theory="${i}" style="margin-top:16px">♫ 听一听</button></div>`).join('')}</div>`);document.querySelectorAll('[data-theory]').forEach(b=>b.onclick=async()=>{stopDemo();silence();try{await ensureAudio()}catch(e){return}const t=D.theory[Number(b.dataset.theory)],now=audio.currentTime+.04;if(t.chord)t.chord.forEach((n,j)=>sound(n,now,1.5,'theory'+j));else if(t.chords)t.chords.forEach((ch,i)=>ch.forEach((n,j)=>sound(n,now+i*1.8,1.5,'theory'+i+j)));else t.notes.forEach((n,i)=>sound(n,now+i*.5,.4,'theory'+i));toast('听一听，也试着在心里记住这个声音。')})}
  function progress(){const days=[];for(let i=27;i>=0;i--){const dt=new Date();dt.setDate(dt.getDate()-i);const key=day(dt),sec=state.history.filter(h=>h.date===key).reduce((s,h)=>s+h.seconds,0);days.push(`<div class="day ${sec?'played':''} ${i===0?'today':''}" title="${key}：${Math.round(sec/60)}分钟"><span>${dt.getDate()}</span><small>${sec?Math.max(1,Math.round(sec/60))+'′':''}</small></div>`)}shell(`<div class="eyebrow">YOUR OWN PACE</div><h1>每一次练习，都算数</h1><p class="muted">与自己比较。找音与节奏模式分开理解。</p><div class="stats"><div class="stat"><span>累计有效练习</span><strong>${totalMinutes()}<small> 分钟</small></strong></div><div class="stat"><span>练习过的天数</span><strong>${new Set(state.history.map(h=>h.date)).size}<small> 天</small></strong></div><div class="stat"><span>已学习课程</span><strong>${state.completed.length}<small> / ${D.lessons.length}</small></strong></div></div><div class="grid"><div class="card"><h2>最近28天</h2><small>方框是今天 · 颜色表示有练习记录</small><div class="heatmap">${days.join('')}</div><p class="audio-note">只统计开始练习后有弹奏活动的时间。停顿较长时暂停计时。</p></div><div class="card"><h2>技能学习地图</h2>${D.stages.map((s,stage)=>{const all=D.lessons.filter(l=>l.stage===stage).length,n=D.lessons.filter((l,i)=>l.stage===stage&&state.completed.includes(i)).length;return `<div class="row between"><small>${s}</small><small>${n}/${all}</small></div><div class="progress"><div style="width:${n/all*100}%"></div></div>`}).join('')}<small>这里展示课程学习进度，不是专业演奏评级。</small></div></div>${state.replays.length?`<div class="card replay-library"><h2>最近的演奏回放</h2><p>保留最近5遍，打开后可以听自己弹的，也可以对照示范。</p>${state.replays.slice().reverse().map((r,i)=>`<div class="row between replay-row"><span>${esc(r.title)}<small> · ${r.bpm} BPM</small></span><button class="small outline" data-replay="${state.replays.length-1-i}">打开回放</button></div>`).join('')}</div>`:''}<div class="section-title"><h2>最近的练习</h2><small>保留最近500次</small></div><div class="card">${state.history.length?state.history.slice(-12).reverse().map(h=>`<div class="history-item"><div class="row between"><b>${esc(h.title)}</b><span class="tag">音高 ${h.pitch}%</span></div><small>${h.date} · ${h.mode==='wait'?'找音':'节奏'} · ${h.bpm} BPM · ${h.seconds}秒${h.timing!==null?' · 命中音起音达标 '+h.timing+'%':''}</small></div>`).join(''):'<div class="empty">还没有练习记录。<br>去曲目页，开始第一遍吧。</div>'}</div>`)}
  function settings(){shell(`<div class="eyebrow">MAKE IT YOURS</div><h1>按你的节奏学习</h1><p class="muted">目标可以调整，记录保存在这台设备上。</p><div class="grid settings-grid"><div class="card"><h2>我的学习目标</h2><label class="field">每天计划练习<input id="minutes" type="number" min="5" max="60" value="${state.minutes}"><small>5—60分钟，不强制完成</small></label><label class="field">想达到的小目标<input id="goal" maxlength="100" value="${esc(state.goal)}" placeholder="例如：弹会小星星开头"></label><label class="field">默认速度 <select id="default-bpm">${[40,50,60,70,80,90,100,120].map(n=>`<option value="${n}" ${n===state.bpm?'selected':''}>${n} BPM</option>`).join('')}${![40,50,60,70,80,90,100,120].includes(state.bpm)?`<option selected value="${state.bpm}">${state.bpm} BPM</option>`:''}</select></label>${notationSelect('default-notation')}<button class="primary" id="save-settings">保存目标</button></div><div class="card"><h2>记录与备份</h2><p>课程与声音都在应用里，无需联网。卸载应用或清除应用数据会删除本地记录，可以先导出备份。</p><div class="row"><button class="outline" id="export">导出记录</button><button class="outline" id="import">导入记录</button></div><div class="callout">横屏适合弹奏，竖屏适合阅读。声音来自本地合成，不需要麦克风或蓝牙权限。</div><p class="audio-note">琴阶 1.4 · iPadOS 16及以上<br>28节课程 · 11首完整旋律＋2个双音版 · 小节循环与回放。时值与真实指法不自动评分。</p>${storageOK?'':'<p>当前存储不可用，请及时导出备份。</p>'}</div></div><input id="import-file" type="file" accept="application/json,.json" hidden>`);$('#save-settings').onclick=()=>{const n=Number($('#minutes').value);if(!Number.isFinite(n)||n<5||n>60){toast('练习时间请填5到60分钟');return}state.minutes=Math.round(n);state.goal=$('#goal').value.trim()||defaultState.goal;state.bpm=Number($('#default-bpm').value);state.notation=$('#default-notation').value;save();toast('已保存。按自己能坚持的节奏来。')};$('#export').onclick=()=>exportFile(JSON.stringify({...state,songPack:library},null,2),'琴阶练习记录-'+day()+'.json','records');$('#import').onclick=()=>{if(window.Android&&Android.importData)Android.importData();else $('#import-file').click()};$('#import-file').onchange=async e=>{const file=e.target.files[0];if(file&&file.size<2000000)window.importPianoState(await file.text());else toast('请选择小于2MB的记录JSON文件')}}
  window.importPianoState=text=>{let oldStateRaw,oldLibraryRaw;try{
    const value=JSON.parse(text.replace(/^\uFEFF/,''));if(value.version!==1||!Array.isArray(value.history)||!Array.isArray(value.completed))throw Error('请选择琴阶记录备份；歌曲包请从曲目页导入');
    const imported=C.safeState(value),pack=value.songPack===undefined?library:L.validate(value.songPack,{allowEmpty:true});
    if(!confirm(value.songPack===undefined?'导入将替换学习记录，自定义曲库保留，是否继续？':'导入将替换学习记录与自定义曲库，是否继续？'))return;
    oldStateRaw=localStorage.getItem('qinjie-state');oldLibraryRaw=localStorage.getItem('qinjie-song-library');
    try{localStorage.setItem('qinjie-song-library',JSON.stringify(pack));localStorage.setItem('qinjie-state',JSON.stringify(imported))}catch(e){try{if(oldStateRaw===null)localStorage.removeItem('qinjie-state');else localStorage.setItem('qinjie-state',oldStateRaw);if(oldLibraryRaw===null)localStorage.removeItem('qinjie-song-library');else localStorage.setItem('qinjie-song-library',oldLibraryRaw)}catch(e){}throw Error('存储空间不足，备份未导入')}
    state=imported;library=pack;mountLibrary();go('settings');toast('记录与曲库已恢复');
  }catch(e){toast('无法导入：'+e.message)}};

  window.nativeNotice=text=>toast(text);
  window.pausePiano=()=>{if(session)finish(false);stopDemo();silence();if(audio)audio.suspend()};
  window.backPiano=()=>go('home');
  function bindActions(){if(route==='practice')$('.main').classList.add('practice-main');document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>go(b.dataset.action));document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{lesson=Number(b.dataset.lesson);go('lesson')});document.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.practice);go('practice');range='all';octave=0;result=null;practice()});document.querySelectorAll('[data-guided]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.guided);go('practice');range='all';beginGuide()});document.querySelectorAll('[data-replay]').forEach(b=>b.onclick=()=>{const r=state.replays[Number(b.dataset.replay)];const index=r.songId?D.exercises.findIndex(e=>e.id===r.songId):r.exercise;if(index<0||!D.exercises[index]){toast('原曲已移除，请重新导入同ID歌曲后打开这份回放。');return}selected=index;go('practice');range='all';result={...C.summarize(r.expected,[],[],r.mode,r.bpm),complete:false,seconds:0,recording:r,expected:r.expected};practice();playRecording(r,false)});document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>demo?stopDemo():playDemo(Number(b.dataset.demo)))}
  const keys={a:60,w:61,s:62,e:63,d:64,f:65,t:66,g:67,y:68,h:69,u:70,j:71,k:72};
  window.addEventListener('keydown',e=>{if(route!=='practice'||e.repeat||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;const n=keys[e.key.toLowerCase()];if(n!==undefined){e.preventDefault();keyPress(n,'key'+e.key.toLowerCase())}});window.addEventListener('keyup',e=>{const n=keys[e.key.toLowerCase()];if(n!==undefined)keyRelease(n,'key'+e.key.toLowerCase())});
  document.addEventListener('visibilitychange',()=>{if(document.hidden){if(session)finish(false);stopDemo();silence();if(audio)audio.suspend()}});window.addEventListener('blur',silence);
  render();
})();
